const TOWNSHIP_COLORS = {
  magong: "#e76f51",
  huxi: "#e9c46a",
  baisha: "#6a994e",
  xiyu: "#457b9d",
  wangan: "#bc4749",
  qimei: "#264653",
};

// 把真實經緯度換算成跟地圖同一套 SVG 座標系，方便把據點畫成地圖上的圖釘
function projectLatLng(lat, lng) {
  const p = PENGHU_MAP.projection;
  const x = lng * p.lonScale;
  const y = -lat;
  return [(x - p.minX) * p.scale + 20, (y - p.minY) * p.scale + 20];
}

// 手繪簡化地圖在少數海岸線細節（小突出、小灣澳）會被簡化掉，準確的 GPS 座標投影後可能剛好落在
// 被簡化掉的那一小段「陸地外」，圖示看起來像浮在海上——不是座標填錯（跟 Google 地圖核對過是準的），
// 也不去動整份手繪地圖資料冒著扭曲整體形狀的風險，改成只對「已知會落在簡化海岸線外」的據點，
// 畫圖示時做幾個像素等級、肉眼看不出偏移的微調，讓圖示落在陸地範圍內。發現新的類似案例，比照這裡加一筆。
// 用據點 id（不是名稱）當 key，後台改名稱不會讓這筆微調悄悄失效
const MARKER_POSITION_OVERRIDES = {
  mywUiRGRbtFvZwrpIxH2: { dx: 6, dy: 7 }, // 重光社區發展協會
};

function projectVenueMarker(venue) {
  const [x, y] = projectLatLng(venue.lat, venue.lng);
  const override = MARKER_POSITION_OVERRIDES[venue.id];
  return override ? [x + override.dx, y + override.dy] : [x, y];
}

// ids 省略時畫全部六個鄉鎮（用固定的整體 viewBox）；
// 有給 ids 時只畫這幾個鄉鎮，並把視角縮放到它們的範圍（首頁「本島」地圖用這個，望安、七美隔太遠會被排除）
function renderPenghuMap(containerId, ids) {
  const el = document.getElementById(containerId);
  if (!el) return;

  const townshipIds = ids || Object.keys(PENGHU_MAP.townships);
  let vx = 0, vy = 0, vw = PENGHU_MAP.width, vh = PENGHU_MAP.height;

  if (ids) {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    ids.forEach((id) => {
      const [a, b, c, d] = PENGHU_MAP.townships[id].bbox;
      x0 = Math.min(x0, a); y0 = Math.min(y0, b); x1 = Math.max(x1, c); y1 = Math.max(y1, d);
    });
    const pad = 20;
    vx = x0 - pad; vy = y0 - pad; vw = (x1 - x0) + pad * 2; vh = (y1 - y0) + pad * 2;
  }

  let svg = `<svg viewBox="${vx} ${vy} ${vw} ${vh}" role="img" aria-label="澎湖縣地圖">`;
  townshipIds.forEach((id) => {
    const t = PENGHU_MAP.townships[id];
    svg += `<path class="township-shape" tabindex="0" data-township="${id}" d="${t.d}" fill="${TOWNSHIP_COLORS[id]}" fill-rule="evenodd" />`;
  });
  // 望安、七美這些小島在地圖上的實際形狀很小，手機上很難點準；疊一個透明的大圓當作保底的點擊熱區
  townshipIds.forEach((id) => {
    const t = PENGHU_MAP.townships[id];
    svg += `<circle class="township-shape township-hit-area" tabindex="-1" data-township="${id}" cx="${t.labelX}" cy="${t.labelY}" r="32" fill="transparent" />`;
  });
  townshipIds.forEach((id) => {
    const t = PENGHU_MAP.townships[id];
    svg += `<text x="${t.labelX}" y="${t.labelY}" text-anchor="middle">${t.name}</text>`;
  });
  svg += "</svg>";
  el.innerHTML = svg;

  el.querySelectorAll(".township-shape").forEach((shape) => {
    const go = () => { location.href = "/township/?id=" + shape.dataset.township; };
    shape.addEventListener("click", go);
    shape.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") go();
    });
  });
}

// 滑鼠移到下方的鄉鎮按鈕，或移到地圖上對應的鄉鎮（本島用地圖形狀，望安、七美用左上角縮圖），
// 兩邊都會讓對方跟著亮起來（呼應），方便使用者對照按鈕跟地圖上的位置
function wireTownshipButtonHover() {
  document.querySelectorAll(".township-buttons .township-button").forEach((btn) => {
    const id = btn.dataset.township;
    const target = document.querySelector(`.township-shape:not(.township-hit-area)[data-township="${id}"]`)
      || document.getElementById(`inset-${id}`);
    if (!target) return;
    btn.addEventListener("mouseenter", () => target.classList.add("highlight"));
    btn.addEventListener("mouseleave", () => target.classList.remove("highlight"));
    target.addEventListener("mouseenter", () => btn.classList.add("highlight"));
    target.addEventListener("mouseleave", () => btn.classList.remove("highlight"));
  });
}

// 離島小地圖（望安、七美）：像放大鏡一樣單獨顯示，不必照實際地理位置擺放。
// 用 mainBbox（只放大本島）而不是完整 bbox，縮圖才不會因為離島太分散而把本島縮到看不清楚
function renderMapInset(containerId, townshipId) {
  const el = document.getElementById(containerId);
  const t = PENGHU_MAP.townships[townshipId];
  if (!el || !t) return;

  const [bx0, by0, bx1, by1] = t.mainBbox;
  const pad = Math.max(8, (bx1 - bx0) * 0.2);
  const vx = bx0 - pad, vy = by0 - pad, vw = (bx1 - bx0) + pad * 2, vh = (by1 - by0) + pad * 2;

  el.innerHTML = `
    <svg viewBox="${vx} ${vy} ${vw} ${vh}" role="img" aria-label="${t.name}">
      <path d="${t.d}" fill="${TOWNSHIP_COLORS[townshipId]}" fill-rule="evenodd" />
    </svg>
    <span class="map-inset-label">${t.name}</span>
  `;
  el.setAttribute("role", "button");
  el.setAttribute("tabindex", "0");
  const go = () => { location.href = "/township/?id=" + townshipId; };
  el.addEventListener("click", go);
  el.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") go();
  });
}

// 詳細頁地圖預設只放大顯示「本島」（mainBbox），每個鄉鎮縮放比例才會一致，不會有些鄉鎮（例如白沙、
// 望安）因為離島散得很開，照完整轄區縮放讓本島變得很小、圖示比例跟地圖對不起來。
// 望安鄉、白沙鄉是目前的例外：望安鄉緊鄰本島的將軍嶼可能有課程據點；白沙鄉的吉貝嶼實際有據點（吉貝
// 惜福長青協會），雖然離本島遠、框進來會讓本島相對縮小，但據點要看得到比本島縮圖好看更重要，所以額外
// 用 detailBbox 把吉貝嶼一起框進來。其餘鄉鎮更遠的離島（虎井、桶盤等）目前沒有另外框，如果之後那些
// 離島也有課程據點要顯示，可以比照這個作法，個別加上 detailBbox。
// township.html 畫運動圖示圖釘時也要用同一個 bbox，不然圖釘大小會跟地圖縮放比例對不起來。
function getTownshipDetailBbox(townshipId) {
  const t = PENGHU_MAP.townships[townshipId];
  return t.detailBbox || t.mainBbox;
}

// 詳細頁地圖實際顯示範圍（viewBox），renderTownshipMap 畫地圖跟 township.html 算圖示大小
// 要用同一份計算，不然地圖縮放跟圖示比例會對不起來。
function getTownshipViewBox(townshipId) {
  const [bx0, by0, bx1, by1] = getTownshipDetailBbox(townshipId);
  const pad = Math.max(5, (bx1 - bx0) * 0.05);
  return { vx: bx0 - pad, vy: by0 - pad, vw: (bx1 - bx0) + pad * 2, vh: (by1 - by0) + pad * 2 };
}

// 圖示的「絕對大小」統一以望安鄉目前的呈現為準：望安鄉的圖示是本島寬度（mainBbox）的 13%，
// 換算成「佔整張地圖畫面的比例」之後，套用同一個比例到其他鄉鎮，這樣不管各鄉鎮地圖範圍大小，
// 圖示在畫面上的絕對大小都會跟望安鄉一致（而不是分別佔各自地圖的固定比例）。
function getMarkerSizeRatio() {
  const wangan = PENGHU_MAP.townships.wangan;
  const [mbx0, , mbx1] = wangan.mainBbox;
  const { vw } = getTownshipViewBox("wangan");
  return ((mbx1 - mbx0) * 0.13) / vw;
}

function renderTownshipMap(containerId, townshipId) {
  const el = document.getElementById(containerId);
  const t = PENGHU_MAP.townships[townshipId];
  if (!el || !t) return;

  const { vx, vy, vw, vh } = getTownshipViewBox(townshipId);

  el.innerHTML = `
    <svg viewBox="${vx} ${vy} ${vw} ${vh}" role="img" aria-label="${t.name}地圖">
      <path d="${t.d}" fill="${TOWNSHIP_COLORS[townshipId]}" fill-rule="evenodd" />
      <g id="township-map-markers"></g>
    </svg>
  `;
}
